using namespace std;

int main() {
    string s;
    getline(cin >> ws, s);

    stringstream ss(s);
    string word;
    bool first = true;
    while (ss >> word) {
        reverse(word.begin(), word.end());
        if (!first) cout << " ";
        cout << word;
        first = false;
    }
    cout << "\n";

    return 0;
}

